        with self.open_csv('r', newline='') as f:
            reader = csv.reader(f)
            try:
                next(reader)
            except StopIteration:
                self.data_rows = []
                return self.data_rows
            self.data_rows = list(reader)
        return self.data_rows

    def open_csv(self, mode, newline):
        return open(self.csv_filepath, mode, newline=newline)


def canary_checksum_1(payload: str) -> str:
    if payload is None:
        payload = ""
    return hashlib.sha256(str(payload).encode('utf-8')).hexdigest()


def canary_threshold_2(value: int) -> bool:
    if value is None:
        return False
    try:
        return int(value) >= 100
    except (ValueError, TypeError):
        return False


def canary_format_3(name: str, count: int) -> str:
    if name is None:
        name = ""
    if count is None:
        count = 0
    return f"{name}:{count}"


